html, body {
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  background: radial-gradient(ellipse at center, #0a0e24 0%, #000000 100%);
  font-family: sans-serif;
  color: white;
  overflow: hidden;
}

.clock {
  position: relative;
  width: 220px;
  height: 220px;
  border-radius: 50%;
  border: 3px solid rgba(75, 154, 170, 0.3);
  box-shadow: 
    0 0 10px rgba(75, 154, 170, 0.5),
    inset 0 0 20px rgba(75, 154, 170, 0.3);
  display: flex;
  justify-content: center;
  align-items: center;
  background: rgba(11, 13, 24, 0.7);
  z-index: 1;
}

.clock::before {
  content: '';
  position: absolute;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  border: 1px solid rgba(116, 199, 217, 0.2);
  box-shadow: 
    inset 0 0 30px rgba(116, 199, 217, 0.1),
    0 0 40px rgba(116, 199, 217, 0.1);
}

.clock__glow {
  position: absolute;
  width: 250px;
  height: 250px;
  border-radius: 50%;
  background: radial-gradient(circle at center, rgba(75, 154, 170, 0.3) 0%, transparent 70%);
  filter: blur(10px);
  z-index: -1;
  animation: pulse 4s infinite alternate;
}

.clock__hand {
  position: absolute;
  bottom: 50%;
  left: 50%;
  transform-origin: bottom center;
  transform: translateX(-50%) rotate(0deg);
  border-radius: 3px;
  z-index: 10;
  box-shadow: 0 0 5px rgba(255, 255, 255, 0.7);
}

.clock__second {
  width: 2px;
  height: 90px;
  background: linear-gradient(to top, #ff4b4b, #ff9999);
  box-shadow: 0 0 10px #ff4b4b;
}

.clock__minute {
  width: 3px;
  height: 80px;
  background: linear-gradient(to top, #ffffff, #cccccc);
  opacity: 0.9;
  box-shadow: 0 0 8px rgba(255, 255, 255, 0.7);
}

.clock__hour {
  width: 4px;
  height: 60px;
  background: linear-gradient(to top, #4b9aaa, #aadddd);
  box-shadow: 0 0 8px rgba(75, 154, 170, 0.7);
}

.clock__axis {
  position: absolute;
  width: 10px;
  height: 10px;
  background: #ff4b4b;
  border-radius: 50%;
  z-index: 11;
  box-shadow: 
    0 0 5px #ff4b4b,
    0 0 10px #ff4b4b;
}

.clock__indicators {
  position: absolute;
  width: 100%;
  height: 100%;
}

.clock__indicators div {
  position: absolute;
  left: 50%;
  width: 2px;
  height: 10px;
  background: rgba(116, 199, 217, 0.7);
  transform-origin: center 110px;
  transform: translateX(-50%) rotate(0deg);
  box-shadow: 0 0 3px rgba(116, 199, 217, 0.9);
}

.clock__indicators div:nth-child(5n) {
  height: 15px;
  width: 3px;
  background: #f4eed7;
  box-shadow: 0 0 5px #f4eed7;
}

@keyframes pulse {
  0% { opacity: 0.3; }
  100% { opacity: 0.7; }
}

/* Add some star effects */
body::before {
  content: '';
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: 
    radial-gradient(2px 2px at 20px 30px, #fff, rgba(0,0,0,0)),
    radial-gradient(2px 2px at 40px 70px, #fff, rgba(0,0,0,0)),
    radial-gradient(2px 2px at 80px 40px, #fff, rgba(0,0,0,0)),
    radial-gradient(2px 2px at 120px 80px, #fff, rgba(0,0,0,0)),
    radial-gradient(2px 2px at 160px 30px, #fff, rgba(0,0,0,0)),
    radial-gradient(2px 2px at 200px 70px, #fff, rgba(0,0,0,0)),
    radial-gradient(2px 2px at 240px 40px, #fff, rgba(0,0,0,0)),
    radial-gradient(2px 2px at 280px 80px, #fff, rgba(0,0,0,0)),
    radial-gradient(2px 2px at 320px 30px, #fff, rgba(0,0,0,0)),
    radial-gradient(2px 2px at 360px 70px, #fff, rgba(0,0,0,0));
  z-index: -2;
}

