// Keep your existing JavaScript exactly the same
document.addEventListener("DOMContentLoaded", () => {
  const secondHand = document.querySelector(".clock__second");
  const minuteHand = document.querySelector(".clock__minute");
  const hourHand = document.querySelector(".clock__hour");
  const indicatorsContainer = document.querySelector(".clock__indicators");

  // Generate indicators dynamically
  for (let i = 0; i < 60; i++) {
    const indicator = document.createElement("div");
    indicator.style.transform = `translateX(-50%) rotate(${i * 6}deg)`;
    indicatorsContainer.appendChild(indicator);
  }

  function updateClock() {
    const now = new Date();
    const seconds = now.getSeconds();
    const minutes = now.getMinutes();
    const hours = now.getHours() % 12;

    secondHand.style.transform = `translateX(-50%) rotate(${seconds * 6}deg)`;
    minuteHand.style.transform = `translateX(-50%) rotate(${minutes * 6}deg)`;
    hourHand.style.transform = `translateX(-50%) rotate(${hours * 30 + minutes * 0.5}deg)`;
  }

  setInterval(updateClock, 1000);
  updateClock(); // Initial call
});
